begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values ('31000000-0000-0000-0000-000000000001'),('31000000-0000-0000-0000-000000000002');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"31000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$insert into public.journal_entries(id,title,body) values ('32000000-0000-0000-0000-000000000001','Synthetic document','Original legacy words')$$,'legacy insert still works');
select lives_ok($$update public.journal_entries set writing_document='{"version":1,"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Revised words"}]}]}}',body='Revised words',page_icon='🌿',cover_preset='dawn' where version=1$$,'owner converts legacy entry with expected version');
select is((select original_body from public.journal_entries),'Original legacy words','first original is preserved privately');
select is((select version from public.journal_entries),2,'conversion advances version');
select throws_ok($$update public.journal_entries set original_body='overwrite'$$,'42501',null,'client cannot overwrite original backup');
select throws_ok($$update public.journal_entries set writing_document='{}'$$,'23514',null,'missing format is rejected');
select throws_ok($$update public.journal_entries set writing_document='{"version":2,"content":{"type":"doc"}}'$$,'23514',null,'future format is rejected');
select throws_ok($$update public.journal_entries set page_icon='<script>'$$,'23514',null,'arbitrary page icon rejected');
select throws_ok($$update public.journal_entries set cover_preset='url(https://tracker.example)'$$,'23514',null,'arbitrary cover CSS or URL rejected');
select throws_ok($$update public.journal_entries set body='Old client overwrite'$$,'23514',null,'old client cannot silently desynchronize a rich document');
select lives_ok($$insert into public.public_stories(id,user_id,title,body,writing_document,page_icon,cover_preset) select id,user_id,title,body,writing_document,page_icon,cover_preset from public.journal_entries$$,'owner explicitly copies reviewed document into public snapshot');
select lives_ok($$update public.journal_entries set writing_document='{"version":1,"content":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Private revision"}]}]}}',body='Private revision',cover_preset='forest' where version=2$$,'owner privately revises rich entry');
select is((select body from public.public_stories),'Revised words','public snapshot remains independent');
select is((select cover_preset from public.public_stories),'dawn','public cover remains independent');
select is((select original_body from public.journal_entries),'Original legacy words','later edits preserve first original');
select lives_ok($$update public.journal_entries set body='stale' where version=2$$,'stale version updates no row');
select is((select body from public.journal_entries),'Private revision','newer writing survives stale request');
select set_config('request.jwt.claims','{"sub":"31000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is((select count(*)::int from public.journal_entries),0,'B cannot read rich private sources or original backups');
select lives_ok($$update public.journal_entries set cover_preset='clay'$$,'B cannot modify A cover');
select lives_ok($$update public.public_stories set page_icon='🌙'$$,'B cannot modify A public icon');
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select is((select cover_preset from public.public_stories),'dawn','anonymous reader receives only chosen public cover');
select is((select page_icon from public.public_stories),'🌿','B attack did not change public icon');
select is((select writing_document->'content'->'content'->0->'content'->0->>'text' from public.public_stories),'Revised words','anonymous reader gets chosen public document only');
select throws_ok($$select original_body from public.journal_entries$$,'42501',null,'anonymous original text denied');
select throws_ok($$select user_id from public.public_stories$$,'42501',null,'public ownership stays hidden');
select throws_ok($$select * from public.public_stories$$,'42501',null,'new fields do not grant wildcard ownership access');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"31000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$update public.public_stories set body='Reviewed plain copy'$$,'old-client publication update remains possible');
select ok((select writing_document is null from public.public_stories),'old-client public edit clears stale structured content');
select lives_ok($$delete from public.public_stories$$,'owner unpublishes');
select is((select count(*)::int from public.journal_entries),1,'unpublish retains private source and original');
reset role;
select * from finish();
rollback;
